def _fastmux():
    "The fastmux module, or None when it or tmux is missing."
    if not shutil.which('tmux'): return None
    try: import fastmux
    except ImportError: return None
    return fastmux

def _pane_cmd(me, command, where, cwd=None):
    "A pane beside `me` running `command`, kept on screen after it exits so the result stays readable."
    import shlex
    keep = f'tmux set-option -p -t "$TMUX_PANE" remain-on-exit on; exec sh -c {shlex.quote(str(command))}'
    return me.split(where, ['sh', '-c', keep], cwd=cwd)

@patch(as_prop=True)
def tmux_pane(self:LocalHost):
    "The pane this host runs in, or None when tmux is off."
    if self._pane is not None: return self._pane
    t = self._tmux
    if t is False or (t is None and not os.environ.get('TMUX')) or (fm := _fastmux()) is None: return None
    p = t if isinstance(t, fm.Pane) else fm.pane(fm._tmux('display-message', '-p', '-t', t, '#{pane_id}').strip()) if isinstance(t, str) else fm.current_pane()
    if not isinstance(p, fm.Pane): raise HostError(f'{t!r} is not a tmux pane')
    self._pane = p
    return self._pane

@patch
def _siblings(self:LocalHost):
    "The other panes in this host's window, the active one first."
    if (me := self.tmux_pane) is None: return []
    return sorted((p for p in _fastmux().Window.fetch(me.window_id).panes if p.id != me.id), key=lambda p: not p.active)

@patch
def open_pane(self:LocalHost, command, title='', where='right'):
    "Show `command` to the user in a new pane beside this one and return its id."
    import subprocess
    if (me := self.tmux_pane) is None: raise HostError('not inside tmux')
    p = _pane_cmd(me, command, where)
    if title: subprocess.run(['tmux', 'select-pane', '-t', p.id, '-T', title], check=True)
    self._panes[p.id] = p
    return p.id

@patch
def close_pane(self:LocalHost, pane_id):
    "Close a pane `open_pane` made."
    if (p := self._panes.pop(pane_id, None)) is None: raise HostError(f'no pane {pane_id!r}')
    try: p.kill()
    except _fastmux().TmuxError: pass

