@patch
def terminal_text(self:LocalHost, lines=200):
    "The neighbouring tmux panes, else what this process recorded in `transcript`."
    n = max(0, int(lines))
    if not (sibs := self._siblings()): return '\n'.join(str(x) for x in (self.transcript[-n:] if n else []))
    out = []
    for p in sibs:
        out += [f'## pane {p.id} ({p.title or p.cmd})', *p.display(max(1, n - len(out))).text.splitlines()]
        if len(out) >= n: break
    return '\n'.join(out[:n])

