PANE_LINES = 2000

def _tail(text, n):
    "The last `n` lines of `text`; all of it when `n` is 0."
    lines = text.splitlines()
    return '\n'.join(lines[-n:] if n else lines)

@patch
def run_cmd_bg(self:LocalHost, command, cwd=None):
    "Start `command` in a tmux pane below this one, else in its own process group with a log file; returns a run id."
    import subprocess, tempfile
    d, rid = self._cwd(cwd), f'cmd_{uuid.uuid4().hex[:8]}'
    if (me := self.tmux_pane) is not None: self._bg[rid] = _pane_cmd(me, command, 'below', cwd=str(d))
    else:
        log = tempfile.NamedTemporaryFile('w', prefix='shalya-bg-', suffix='.log', delete=False)
        p = subprocess.Popen(str(command), shell=True, cwd=str(d), stdout=log, stderr=subprocess.STDOUT, start_new_session=True)
        log.close()
        self._bg[rid] = (p, Path(log.name))
    return rid

@patch
def _bg_run(self:LocalHost, run_id):
    "What a run id holds: `(process, log)`, a live `Pane`, or the `{state, text}` a stopped pane left."
    if (r := self._bg.get(run_id)) is None: raise HostError(f'no background command {run_id!r}')
    return r

@patch
def cmd_output(self:LocalHost, run_id, tail=200):
    "`(state, text)`: `running`, `exit N` or `stopped`, and the last `tail` lines so far."
    r = self._bg_run(run_id)
    if isinstance(r, tuple):
        p, log = r
        code = p.poll()
        state = 'running' if code is None else 'stopped' if code < 0 else f'exit {code}'
        return state, _tail(log.read_text(errors='replace') if log.exists() else '', tail)
    if 'state' in r: return r['state'], _tail(r['text'], tail)
    try: code = r.wait(timeout_ms=0); return ('running' if r.running else f'exit {code}' if code is not None else 'stopped'), r.display(tail or PANE_LINES).text
    except _fastmux().TmuxError: return 'stopped', ''

@patch
def cmd_stop(self:LocalHost, run_id):
    "Kill a background command, or clear its finished pane; returns its state afterwards."
    import signal
    r = self._bg_run(run_id)
    if isinstance(r, tuple):
        p = r[0]
        if p.poll() is None:
            try: os.killpg(p.pid, signal.SIGKILL)
            except Exception: p.kill()
            p.wait(5)
        return self.cmd_output(run_id, 0)[0]
    if 'state' in r: return r['state']
    state, text = self.cmd_output(run_id, 200)
    r.kill()
    self._bg[run_id] = dict(state='stopped' if state == 'running' else state, text=text)
    return self._bg[run_id]['state']

@patch
def close(self:LocalHost):
    "Stop every background command and pane this host opened, and drop the logs."
    for rid in list(self._bg):
        self.cmd_stop(rid)
        if isinstance((r := self._bg.pop(rid)), tuple): r[1].unlink(missing_ok=True)
    for pid in list(self._panes): self.close_pane(pid)

