def _venv_python(p):
    "The interpreter and version a venv folder offers, or None."
    py, cfg = p/'bin'/'python', p/'pyvenv.cfg'
    if not py.exists(): return None
    v = cfg.exists() and re.search(r'^version\s*=\s*(.+)$', cfg.read_text(), re.M)
    return f'{py} ({v[1].strip()})' if v else str(py)

@patch
def environment(self:LocalHost):
    "This process, the venvs under the open folders, and the commands on PATH; computed once per set of roots."
    if self._env is not None: return self._env
    lines = [f'this process: {sys.executable}; kernel {self.kernel_kind}; inspect_python honours {", ".join(self.scopes)}']
    lines += [f'venv: {v}' for r in self._roots for p in sorted(Path(r).glob('*venv*')) if (v := _venv_python(p))]
    lines += [f'{c}: {shutil.which(c) or "not on PATH"}' for c in ('python', 'uv', 'ffmpeg', 'rg')]
    lines.append(f'tmux: {me.session}:{me.win} pane {me.id}' if (me := self.tmux_pane) is not None else 'tmux: off')
    self._env = '\n'.join(lines)
    return self._env

