# %% ../nbs/01_host.ipynb #abb87c05
#: Where the article is when a page does not say. Each is tried; the best-scoring one wins.
CONTENT_SEL = ('article', 'main', '[role="main"]', '.article-body', '.article-content',
               '.post-content', '.entry-content')
#: The blocks an article is built from, for a page whose wrapper is none of the above.
BLOCK_SEL = ', '.join(f'{root} {tag}' for root in ('article', 'main', '[role="main"]')
                      for tag in ('h1', 'h2', 'h3', 'h4', 'p', 'pre', 'blockquote', 'li', 'table'))
THIN_PAGE = 800      #: characters below which a fetch answered with a shell, not a page
MAX_PAGE = 200_000   #: characters of one page kept
MIN_SECTION = 80     #: characters below which a repeated `<article>` is a card, not a document
#: url pattern -> the fossick reader for it, its arguments, and what its result is.
READERS = (
    (re.compile(r'https?://(www\.)?github\.com/[^/]+/[^/]+/(blob|raw)/', re.I), 'read_gh_file', {}, 'repo'),
    (re.compile(r'https?://(www\.)?arxiv\.org/(abs|pdf)/', re.I), 'read_arxiv', dict(save_pdf=False, source=True), 'paper'),
    (re.compile(r'https?://(www\.)?(youtube\.com/watch|youtu\.be/)', re.I), 'read_yt', {}, 'page'),
)

def md_title(md, url=''):
    "The first markdown heading, else the url's last path segment."
    for line in str(md).split('\n', 40)[:40]:
        if line.startswith('#'): return line.lstrip('#').strip()[:120]
    return Path(str(url).rstrip('/')).name or str(url)

def _quality(text):
    "Length, less the bullet fraction: a page that is mostly bullets is a nav column, not an article."
    lines = [x for x in text.splitlines() if x.strip()]
    bullets = sum(x.lstrip().startswith(('* ', '- ')) for x in lines)
    return len(text) * (1 - bullets / max(1, len(lines)))

def _page_text(fossick, page, sel=None, mx=MAX_PAGE):
    "The best markdown a fetched page yields, and the strategy that produced it."
    candidates = []
    def take(label, **kw):
        try: text = str(fossick.to_md(page, **kw) or '').strip()
        except Exception: return
        if text: candidates.append((label, text))
    if sel: take(f'selector {sel}', sel=sel, multi=True)   # without `multi` a selector takes its first match only
    take('readability')
    for one in CONTENT_SEL: take(one, sel=one, multi=True)
    take('semantic blocks', sel=BLOCK_SEL, multi=True)
    if not candidates: return '', 'no extraction matched'
    label, text = max(candidates, key=lambda row: _quality(row[1]))
    return text[:mx], label

def _sections(fossick, page, mx=MAX_PAGE):
    "Repeated `<article>` elements as separate documents. Fewer than two of them is one page."
    try: elements = list(page.css('article'))
    except Exception: return []
    out, seen = [], set()
    for element in elements:
        try:
            heading = element.css('h1, h2, h3').first
            title = heading.get_all_text().strip() if heading is not None else ''
            text = str(fossick.to_md(str(element.get())) or '').strip()
            if len(list(element.css('article'))) > 1:   # a wrapper: its own first line names it
                title = first(ln.strip().lstrip('#').strip()[:120] for ln in text.splitlines() if ln.strip()) or ''
        except Exception: continue
        key = ' '.join(text.lower().split())
        if len(text) < MIN_SECTION or key in seen: continue
        seen.add(key)
        out.append({'title': title or md_title(text), 'text': text[:mx]})
    return out if len(out) > 1 else []

def _extracted(rows):
    "One or many extraction rows as one markdown blob, whichever key this fossick names the body."
    def body(row):
        if isinstance(row, dict): return str(row.get('content') or row.get('body') or row.get('text') or '')
        return str(row or '')
    return '\n\n'.join(x for x in (body(r).strip() for r in (rows if isinstance(rows, list) else [rows])) if x)

_READER_KIND = {'arxiv': 'paper', 'ghfile': 'repo', 'youtube': 'page', 'pdf': 'page'}
_READER_STRATEGY = {'arxiv': 'read_arxiv', 'ghfile': 'read_gh_file', 'youtube': 'read_yt', 'pdf': 'pdf2md'}

def _reader_doc(fossick, url, say, mx):
    "A target fossick reads with a dedicated reader (arxiv, gh file, youtube, pdf), adapted to read_page's contract."
    what_is = getattr(fossick, 'what_is', None)
    try: kind = what_is(url) if what_is else None
    except Exception: kind = None
    if kind not in _READER_KIND: return None
    try: res = fossick.read(url)
    except Exception as e:
        say(f'read could not read {url} ({host_err(e)}); fetching the page')
        return None
    if not (res and res.get('ok') and str(res.get('text') or '').strip()): return None
    text = str(res['text'])[:mx]
    return AttrDict(text=text, url=res.get('source') or url, title=res.get('title') or md_title(text, url),
                    kind=_READER_KIND[kind], sections=[], strategy=_READER_STRATEGY[kind])

def read_page(fossick, url, sel=None, note=None, readers=READERS, thin=THIN_PAGE, mx=MAX_PAGE):
    """One url as markdown, or None. `sel` is a css selector to prefer over every guess.

    `text`, `url`, `title`, `kind`, `sections`, and the `strategy` that produced the text.
    """
    url, say = str(url or '').strip(), note or (lambda msg: None)
    if not url: return None
    if getattr(fossick, 'read', None) is not None:      # fossick reads arxiv/gh/youtube/pdf itself
        if (got := _reader_doc(fossick, url, say, mx)) is not None: return got
    else:
        for rx, name, kw, kind in readers:              # a fossick without `read`: shalya's own dispatch
            if not rx.search(url) or (reader := getattr(fossick, name, None)) is None: continue
            try: got = reader(url, **kw)
            except Exception as e:   # a reader that cannot answer is not a url that cannot be read
                say(f'{name} could not read {url} ({host_err(e)}); fetching the page')
                break
            if (text := _md_doc(got)).strip():
                titled = str(got.get('title') or '') if isinstance(got, dict) else ''
                return AttrDict(text=text[:mx], url=url, title=titled or md_title(text, url),
                                kind=kind, sections=[], strategy=name)
            break
    try: page = fossick.fetch(url, auto=True)
    except Exception as e:
        say(f'could not fetch {url} ({host_err(e)})')
        page = None
    text, strategy = _page_text(fossick, page, sel, mx) if page is not None else ('', 'nothing fetched')
    sections = _sections(fossick, page, mx) if page is not None and not sel else []
    if len(text.strip()) < thin:
        reached = getattr(page, 'tier', None) in ('stealthy', 'stealthy+session', 'blocked')
        for opts in ({'heavy': True, 'network_idle': True}, {'stealthy': True}):
            if opts.get('stealthy') and reached: continue   # `auto` already escalated to stealthy; a manual retry only repeats it
            try: heavy = fossick.fetch(url, **opts)
            except Exception: continue
            if heavy is None: continue
            richer, label = _page_text(fossick, heavy, sel, mx)
            if not sel and len(rich := _sections(fossick, heavy, mx)) > len(sections): sections = rich
            if len(richer) > len(text): page, text, strategy = heavy, richer, f'rendered {label}'
            if len(text.strip()) >= thin: break
    if len(text.strip()) < thin and hasattr(fossick, 'extract'):
        try: fallback = _extracted(fossick.extract(url))
        except Exception: fallback = ''
        if len(fallback) > len(text): text, strategy = fallback[:mx], 'independent extraction'
    if page is not None and (ld := ld_json(getattr(page, 'html_content', '') or '')):
        text = f'<structured-data>\n{json.dumps(ld)[:LD_CHARS]}\n</structured-data>\n\n{text}'
    if not text.strip(): return None
    return AttrDict(text=text, url=url, title=md_title(text, url), kind='page',
                    sections=sections, strategy=strategy)

